mapper.update:
UPDATE payment SET payment_key = #{paymentKey}, status = 'PAID', method = #{method},
                   approved_at = #{approvedAt}, paid_at = now(), updated_at = now()
WHERE id = #{id,typeHandler=com.platform.reservation.UuidTypeHandler}

UPDATE reservation SET status = 'CONFIRMED', confirmed_at = now(), updated_at = now()
WHERE id = #{reservationId,typeHandler=com.platform.reservation.UuidTypeHandler}
  AND status = 'PENDING'

UPDATE payment SET status = 'CANCEL_REQUESTED', cancelled_amount = #{cancelledAmount},
                   updated_at = now()
WHERE id = #{id,typeHandler=com.platform.reservation.UuidTypeHandler}
